import pytest
from conftest import ApiClient, ApiHelper

@pytest.mark.parametrize("username, password, expected_status", [
    ("valid_user", "valid_pass", 200),
    ("invalid_user", "invalid_pass", 400),
    (None, None, 400),
])
def test_login_user(api_client: ApiClient, username, password, expected_status):
    """
    Test the /user/login endpoint with various credentials.
    """
    params = {}
    if username is not None:
        params['username'] = username
    if password is not None:
        params['password'] = password

    response = api_client.get("/user/login", params=params)
    assert response.status_code == expected_status

    if expected_status == 200:
        assert 'X-Rate-Limit' in response.headers
        assert 'X-Expires-After' in response.headers
        assert response.headers['Content-Type'] in ['application/xml', 'application/json']
    elif expected_status == 400:
        assert response.json().get('message') == "Invalid username/password supplied"

def test_login_user_missing_auth(api_client: ApiClient):
    """
    Test the /user/login endpoint with missing authentication.
    """
    response = api_client.get("/user/login")
    assert response.status_code == 400
    assert response.json().get('message') == "Invalid username/password supplied"

